/* Preflop hand classes, strength percentiles and "top X%" ranges. */
(function (root) {
  'use strict';
  const PA = (root.PA = root.PA || {});
  const { RANKS } = PA.Cards;

  // Strongest to weakest; generated by tools/generate-rankings.js (blend of heads-up and 4-way equity).
  const ORDER = ["AA","KK","QQ","JJ","TT","99","AKs","AQs","88","AJs","AKo","ATs","AQo","77","KQs","KJs","AJo","KTs","A9s","ATo","KQo","66","A8s","QJs","KJo","A7s","K9s","QTs","KTo","A9o","A5s","QJo","A6s","JTs","A8o","A4s","Q9s","K8s","55","A3s","QTo","J9s","A7o","K7s","K9o","A2s","Q8s","JTo","A5o","K6s","A6o","Q9o","T9s","K5s","A4o","K4s","J8s","K8o","44","Q7s","T8s","A3o","K3s","Q6s","J9o","K7o","A2o","J7s","98s","Q8o","T9o","K6o","K2s","Q5s","T7s","33","J8o","K5o","Q4s","J6s","97s","K4o","Q7o","T8o","87s","Q3s","J5s","Q6o","T6s","Q2s","98o","J4s","K3o","J7o","86s","96s","Q5o","K2o","J3s","22","76s","97o","T7o","T5s","J2s","Q4o","T4s","95s","87o","75s","J6o","85s","Q3o","65s","T3s","J5o","T6o","T2s","94s","Q2o","54s","96o","J4o","76o","74s","64s","93s","84s","86o","J3o","92s","T5o","J2o","83s","T4o","53s","85o","95o","63s","75o","73s","T3o","43s","65o","82s","T2o","94o","52s","54o","93o","74o","62s","72s","84o","42s","64o","92o","32s","83o","63o","53o","82o","43o","73o","52o","72o","62o","42o","32o"];

  const comboCount = (name) => (name.length === 2 ? 6 : name[2] === 's' ? 4 : 12);

  const PERCENTILE = {};
  const INDEX = {};
  (function build() {
    let cum = 0;
    ORDER.forEach((name, i) => {
      INDEX[name] = i;
      const n = comboCount(name);
      PERCENTILE[name] = (cum + n / 2) / 1326;
      cum += n;
    });
  })();

  function handClass(cards) {
    const r1 = cards[0] >> 2, r2 = cards[1] >> 2;
    const hi = Math.max(r1, r2), lo = Math.min(r1, r2);
    if (hi === lo) return RANKS[hi] + RANKS[lo];
    return RANKS[hi] + RANKS[lo] + ((cards[0] & 3) === (cards[1] & 3) ? 's' : 'o');
  }

  /** 0 = best hand (AA), 1 = worst (32o). */
  function percentile(cards) {
    return PERCENTILE[handClass(cards)];
  }

  function combosOf(name) {
    const hi = RANKS.indexOf(name[0]), lo = RANKS.indexOf(name[1]);
    const out = [];
    for (let s1 = 0; s1 < 4; s1++) for (let s2 = 0; s2 < 4; s2++) {
      if (name.length === 2) { if (s2 > s1) out.push([hi * 4 + s1, lo * 4 + s2]); }
      else if (name[2] === 's') { if (s1 === s2) out.push([hi * 4 + s1, lo * 4 + s2]); }
      else if (s1 !== s2) out.push([hi * 4 + s1, lo * 4 + s2]);
    }
    return out;
  }

  const rangeCache = new Map();
  /** All combos in the [from, to) percentile window, e.g. topRange(0, 0.15) = top 15% of hands. */
  function rangeCombos(from, to) {
    const key = from.toFixed(3) + ':' + to.toFixed(3);
    if (rangeCache.has(key)) return rangeCache.get(key);
    const out = [];
    for (const name of ORDER) {
      const p = PERCENTILE[name];
      if (p >= from && p <= Math.max(to, 0.005)) out.push(...combosOf(name));
    }
    if (!out.length) out.push(...combosOf('AA'));
    rangeCache.set(key, out);
    return out;
  }

  function classesInTop(pct) {
    return ORDER.filter((n) => PERCENTILE[n] <= pct);
  }

  /** Short human description of a percentile range for the UI, e.g. "top 15% (88+, ATs+, KQs...)". */
  function describeTop(pct) {
    const names = classesInTop(pct);
    return 'top ' + Math.round(pct * 100) + '% (' + names.slice(0, 6).join(', ') + (names.length > 6 ? ', ...' : '') + ')';
  }

  PA.Ranges = { ORDER, PERCENTILE, handClass, percentile, combosOf, rangeCombos, classesInTop, describeTop };
  if (typeof module !== 'undefined' && module.exports) module.exports = PA.Ranges;
})(typeof globalThis !== 'undefined' ? globalThis : this);
